LINKS = ["base_link", "shoulder_link", "upper_arm_link", "forearm_link", "wrist_1_link", "wrist_2_link", "wrist_3_link", "tool0", "tcp"]
def check(ctx):
    out = {}
    for n in LINKS:
        try:
            t = ctx.transform("world", n)
            out[n] = [round(t["translation"]["x"], 3), round(t["translation"]["y"], 3), round(t["translation"]["z"], 3)]
        except ValueError as e:
            out[n] = "err"
    ctx.state["links"] = out
    ctx.state["frames"] = ctx.frame_ids()
    return None

OID = "u_green"
def check(ctx):
    p = ctx.object_pose(OID)
    if p is None:
        return None
    pos = p["pose"]["position"]
    if "ref" not in ctx.state:
        ctx.state["ref"] = pos
        return None
    d = ctx.dist(pos, ctx.state["ref"])
    if d > ctx.value("tol_m"):
        return {"value": d, "detail": OID + " displaced %.4f m from rest pose" % d}
    return None

