def check(ctx):
    d = ctx.depth()
    if d is None:
        return None
    best = None
    for v in range(168, 190, 2):
        for u in range(364, 388, 2):
            z = float(d[v, u])
            if z == z:
                p = ctx.deproject(u, v, z)
                if best is None or p["z"] > best["z"]:
                    best = {"u": u, "v": v, "x": p["x"], "y": p["y"], "z": p["z"]}
    ctx.state["top"] = best
    return None
